using System.Security.Cryptography;
using System.Text;

namespace Apogeu.Security.Tests.Support;

/// <summary>An operator API key generated by the test (never a real credential): random id and random secret.</summary>
internal sealed record TestApiKey(string Id, string Secret)
{
    public byte[] SecretBytes => Encoding.UTF8.GetBytes(Secret);

    public static TestApiKey Generate() =>
        new("it-" + Convert.ToHexStringLower(RandomNumberGenerator.GetBytes(8)), Convert.ToHexStringLower(RandomNumberGenerator.GetBytes(32)));
}
